#include <stdio.h> int main(){ int i,j,n,index,min,flag = 0; printf("Enter the number of elements in the array:"); scanf("%d",&n); int array[n]; printf("Enter the elements of array
"); for(i = 0; i < n; i ++){ printf("Enter the element: "); scanf("%d",&array[i]); } printf("The given array is:
"); for(i = 0;i < n; i ++){ printf("%d	 ",array[i]); } min = array[0]; for(i = 0;i < n;i ++){ for(j = i + 1;j < n;j ++){ if(min > array[j]){ flag = 1; min = array[j]; index = j; }else{ continue; } } if(flag == 1){ array[index] = array[i]; array[i] = min; min = array[i + 1]; }else{ min = array[i + 1]; } } printf("The sorted array is:
"); for(i = 0;i < n; i ++){ printf("%d	 ",array[i]); } return 0; }

